"use client";
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import type {HandoffScope} from '@/lib/cashier-handoff';
type Request={id:string;code:string;label:string};
export function CashierBankAccountCreate({scope,onSaved}:{scope:HandoffScope;onSaved:()=>void}){
 const [cancelConfirmed,setCancelConfirmed]=useState(false),[pending,setPending]=useState<Request|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');const alive=useRef(false),lock=useRef(false),key='irp.bank.setup.v1:'+ [scope.tenant,scope.property,scope.actor].join(':');
 function checked(r:Request){if(!r||typeof r.id!=='string'||!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(r.id)||typeof r.code!=='string'||!/^[a-z0-9][a-z0-9_-]{1,39}$/.test(r.code)||typeof r.label!=='string'||r.label!==r.label.trim()||r.label.length<2||r.label.length>80||/[\x00-\x1f\x7f]/.test(r.label))throw Error('Review the bank code and nickname.');return {id:r.id,code:r.code,label:r.label}}
 function read(){const raw=sessionStorage.getItem(key);return raw===null?null:checked(JSON.parse(raw))}
 useEffect(()=>{alive.current=true;try{setPending(read())}catch(e){setError(e instanceof Error?e.message:'Unable to recover account setup.')}return()=>{alive.current=false}},[key]);
 async function identify(){const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen bank setup.');}
 async function save(request:Request,status=false){if(lock.current)return;lock.current=true;setBusy(true);setError('');setMessage('');try{const r=checked(request);await identify();if(!alive.current)return;const prior=read();if(prior&&JSON.stringify(prior)!==JSON.stringify(r))throw Error('Recover the pending account first.');const encoded=JSON.stringify(r);sessionStorage.setItem(key,encoded);if(sessionStorage.getItem(key)!==encoded)throw Error('Unable to preserve account recovery.');setPending(r);
 const value=await hotelRpc(status?'cashier_bank_account_status':'register_cashier_bank_account',status?{p_tenant:scope.tenant,p_property:scope.property,p_request:r.id}:{p_tenant:scope.tenant,p_property:scope.property,p_request:r.id,p_code:r.code,p_label:r.label,p_confirmed:true});await identify();if(!alive.current)return;let v=value as Record<string,unknown>;if(status){if(!v||v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.request_id!==r.id||typeof v.found!=='boolean')throw Error('Account recovery scope changed.');if(!v.found){if(v.result!==null)throw Error('Invalid account recovery.');setMessage('No saved account found. Retry the original setup.');return}v=v.result as Record<string,unknown>}
 if(!v||v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.account_id!==r.id||v.code!==r.code||v.label!==r.label||v.currency!=='USD'||v.bank_connected!==false||typeof v.replayed!=='boolean'||typeof v.created_at!=='string')throw Error('Account receipt does not match the setup.');sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('Unable to clear account recovery.');setPending(null);setMessage('Bank account configured. No bank connection was created. Refresh received cash to select it.');onSaved();
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Setup interrupted. Check its saved result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 async function cancel(){if(lock.current||!pending||!cancelConfirmed)return;const request=pending.id;lock.current=true;setBusy(true);setError('');setMessage('');try{await identify();if(!alive.current)return;const value=await hotelRpc('cancel_cashier_bank_action',{p_tenant:scope.tenant,p_property:scope.property,p_request:request,p_kind:'setup',p_confirmed:true});await identify();if(!alive.current)return;const v=value as Record<string,unknown>;if(!v||v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.request_id!==request||v.kind!=='setup'||v.cancelled!==true||typeof v.replayed!=='boolean'||typeof v.created_at!=='string')throw Error('Cancellation receipt does not match the request.');const current=read();if(current&&current.id!==request)throw Error('A different request is pending.');sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('Unable to clear pending request.');setPending(null);setCancelConfirmed(false);setMessage('Unrecorded setup cancelled. Delayed retries cannot create it.')}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Cancellation interrupted. Retry to confirm the result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section><h3>Configure a bank account</h3><p>Use an internal code and nickname. Do not enter bank passwords or account numbers.</p>{pending?<><p>Pending account: {pending.label} ({pending.code})</p><button disabled={busy} onClick={()=>void save(pending)}>Retry account setup</button><button disabled={busy} onClick={()=>void save(pending,true)}>Check account setup</button><label><input type="checkbox" checked={cancelConfirmed} disabled={busy} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel this unrecorded request.</label><button disabled={busy||!cancelConfirmed} onClick={()=>void cancel()}>Cancel pending setup</button></>:<form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void save({id:crypto.randomUUID(),code:String(f.get('code')).trim(),label:String(f.get('label')).trim()})}}><fieldset disabled={busy}><label className="field">Internal bank code<input name="code" required pattern="[a-z0-9][a-z0-9_-]{1,39}" placeholder="operating"/></label><label className="field">Bank account nickname<input name="label" required minLength={2} maxLength={80}/></label><label><input type="checkbox" required/>I confirm this account nickname and internal code.</label><button>Configure bank account</button></fieldset></form>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>
}
